pub struct ConnectionsApi<'a, T> {
    client: &'a crate::runtime::Client<T>,
}

impl<'a, T: crate::runtime::Transport> ConnectionsApi<'a, T> {
    /// The `connection_providers` collection.
    pub fn connection_providers(&self) -> ConnectionProvidersCollection<'a, T> {
        ConnectionProvidersCollection {
            client: self.client,
        }
    }

    /// The `connections` collection.
    pub fn connections(&self) -> ConnectionsCollection<'a, T> {
        ConnectionsCollection {
            client: self.client,
        }
    }
}

